"""`__pycache__/` and `.suite-cache*.out` are regenerated by every test run
and must stay untracked (see .gitignore). A tracked copy is rewritten with
every run and shows up as a spurious `git status` change, which makes a
finished, content-clean worktree look "dirty" to tooling that checks for a
clean tree.

python3 -m pytest -q tests/test_repo_cache_artifacts.py
"""
from __future__ import annotations

import subprocess
from pathlib import Path

REPO = Path(__file__).resolve().parents[1]


def _tracked_files() -> list[str]:
    result = subprocess.run(
        ["git", "-C", str(REPO), "ls-files"],
        capture_output=True, text=True, check=True,
    )
    return result.stdout.splitlines()


def test_no_pycache_dirs_tracked():
    hits = [rel for rel in _tracked_files() if "__pycache__/" in rel]
    assert hits == []


def test_no_suite_cache_files_tracked():
    hits = [rel for rel in _tracked_files()
            if Path(rel).name.startswith(".suite-cache") and rel.endswith(".out")]
    assert hits == []
